const $=id=>document.getElementById(id);
const KEY='idea-forge-v1'; let ideas=[], current=null, filter='all', provider=null, engine=null, busy=false;
const sample=[{title:'地域の「得意」をつなぐ交換所',category:'コミュニティ',body:'料理を教える代わりに、写真を撮ってもらう。近所の人どうしで得意を交換できる場所をつくりたい。',plan:'対象ユーザー：地域でつながりをつくりたい人\n提供する価値：お金以外の方法で助け合える\n最小限の機能：得意の投稿、検索、交換リクエスト\n最初の一歩：近所の5人に交換したいことを聞く。'},{title:'毎日5分の、学びの記録',category:'学び',body:'学んだことを一言で残し、1週間ごとに振り返る小さな学習ノート。続けるほど、自分の成長が見える。',plan:''}];
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500)}
try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if(!Array.isArray(v)||v.some(x=>!x||typeof x.id!=='string'||typeof x.title!=='string'||typeof x.body!=='string'||typeof x.plan!=='string'))throw Error('形式が不正です');ideas=v}else{ideas=sample.map(x=>({...x,id:crypto.randomUUID(),updated:new Date().toISOString(),sample:true,proofs:[]}));localStorage.setItem(KEY,JSON.stringify(ideas))}}catch(e){toast('保存データを読み込めません。ブラウザの保存設定をご確認ください。')}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));ideas=next;render();return true}catch(e){toast('端末に保存できませんでした。書き出して内容を保管してください。');return false}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function isRecorded(x){return (x.proofs||[]).some(p=>p.status==='confirmed'&&p.snapshot===canonical(x))}
function render(){const q=$('search').value.trim().toLowerCase();$('count').textContent=ideas.length;$('navCount').textContent=ideas.length;const cards=$('cards');cards.replaceChildren();const shown=ideas.filter(x=>(filter==='all'||(filter==='recorded'?isRecorded(x):!isRecorded(x)))&&[x.title,x.body,x.category,x.plan].join(' ').toLowerCase().includes(q));for(const x of shown){const c=el('button','card');const top=el('div','card-top');top.append(el('span','card-icon',({暮らし:'⌂',学び:'↗',コミュニティ:'◎',仕事:'▤',クリエイティブ:'✳'})[x.category]||'✧'),el('span','badge'+(isRecorded(x)?' recorded':''),isRecorded(x)?'✓ 記録済み':x.sample?'サンプル · 下書き':'下書き'));const bottom=el('div','card-bottom');bottom.append(el('span','',x.category+' · '+new Date(x.updated).toLocaleDateString('ja-JP',{month:'2-digit',day:'2-digit'})),el('span','','↗'));c.append(top,el('h3','',x.title||'無題のアイデア'),el('p','',x.body),bottom);c.onclick=()=>openEditor(x);cards.append(c)}if(!shown.length&&(q||filter!=='all'))cards.append(el('p','empty','該当するアイデアはありません。'));const add=el('button','card new-card');add.append(el('strong','','＋'),el('b','','次のひらめきを、ここに。'),el('span','','新しいアイデアをつくる'));add.onclick=()=>openEditor();cards.append(add)}
function canonical(x){return JSON.stringify({version:1,title:x.title,category:x.category,body:x.body,plan:x.plan})}
async function digest(x){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(x))))].map(b=>b.toString(16).padStart(2,'0')).join('')}
function formValue(){return {...current,title:$('title').value.trim(),category:$('category').value,body:$('idea').value.trim(),plan:$('plan').value.trim(),updated:new Date().toISOString(),sample:false}}
function save(quiet=false){const x=formValue();if(!x.title||!x.body){toast('アイデア名と内容を入力してください。');return null}if(!persist([x,...ideas.filter(v=>v.id!==x.id)]))return null;current=x;$('saveStatus').textContent='保存済み · '+new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});if(!quiet)toast('アイデアを保存しました');renderProof();return x}
function openEditor(x){current=x?structuredClone(x):{id:crypto.randomUUID(),title:'',body:'',plan:'',category:'暮らし',proofs:[]};for(const [id,key]of [['title','title'],['idea','body'],['plan','plan'],['category','category']])$(id).value=current[key];$('consent').checked=false;$('aiStatus').textContent='AIはWebGPU対応ブラウザで実行します。初回は約1GBのモデル取得に数分かかる場合があります。';$('saveStatus').textContent=x?'このブラウザに保存されています。':'保存すると、このブラウザに残ります。';$('delete').hidden=!x;renderProof();$('editor').showModal()}
function renderProof(){const area=$('proof');area.replaceChildren();for(const p of [...(current.proofs||[])].reverse()){area.append(el('p','',p.status==='confirmed'?'✓ 記録確認済み'+(p.snapshot!==canonical(formValue())?'（編集前の内容）':''):p.status==='failed'?'記録失敗':'送信済み · 確認が必要'));const a=el('a','','Solana Explorerで確認 ↗');a.href='https://explorer.solana.com/tx/'+encodeURIComponent(p.signature)+'?cluster=devnet';a.target='_blank';a.rel='noopener noreferrer';area.append(a);if(p.status==='pending'){const b=el('button','text-button','確認状態を再取得');b.onclick=()=>checkProof(p);area.append(b)}}}
for(const id of ['newHero','newSidebar'])$(id).onclick=()=>openEditor();$('allIdeas').onclick=()=>{$('search').value='';document.querySelector('[data-filter="all"]').click();document.querySelector('.library').scrollIntoView({behavior:'smooth'})};$('save').onclick=()=>save();$('search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(v=>v.classList.toggle('selected',v===b));render()});
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('exportAll').onclick=()=>download({format:'idea-forge-v1',exportedAt:new Date().toISOString(),ideas},'idea-forge-backup.json');$('download').onclick=()=>download(formValue(),'idea-forge-'+current.id+'.json');$('delete').onclick=()=>{if(busy)return;if(confirm('このアイデアを端末から削除しますか？チェーン上の記録は削除されません。')&&persist(ideas.filter(x=>x.id!==current.id))){$('editor').close();toast('アイデアを削除しました')}};
function getProvider(){return window.phantom?.solana||window.solflare||window.solana}
async function connect(){provider=getProvider();if(!provider){toast('PhantomまたはSolflareのブラウザ拡張を入れてから接続してください。');return false}await provider.connect();const key=provider.publicKey.toString();$('wallet').textContent=key.slice(0,4)+'…'+key.slice(-4)+' · 接続済み';return true}
$('wallet').onclick=async()=>{try{await connect()}catch(e){toast('ウォレットの接続がキャンセルされたか、接続できませんでした。')}};
async function solana(){if(!globalThis.Buffer){const b=await import('https://esm.sh/buffer@6.0.3');globalThis.Buffer=b.Buffer}return import('https://esm.sh/@solana/web3.js@1.98.4?bundle')}
function lock(v){busy=v;for(const id of ['save','generate','record','delete','title','category','idea','plan','consent'])$(id).disabled=v;$('editor').querySelector('.icon-button').disabled=v}
$('editor').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('editor').querySelector('form').addEventListener('submit',e=>{if(busy)e.preventDefault()});
$('generate').onclick=async()=>{if(busy)return;if(!$('idea').value.trim()){toast('まずアイデアの内容を書いてください。');return}if($('plan').value.trim()&&!confirm('現在のプロダクトプランをAIで書き換えますか？'))return;lock(true);try{if(!navigator.gpu)throw Error('このブラウザはWebGPUに対応していません。PC版ChromeやEdgeでお試しください。企画は手入力でも保存できます。');if(!engine){$('aiStatus').textContent='AIモデルを準備しています…';const {CreateMLCEngine}=await import('https://esm.run/@mlc-ai/web-llm@0.2.79');engine=await CreateMLCEngine('Qwen2.5-1.5B-Instruct-q4f16_1-MLC',{initProgressCallback:p=>{$('aiStatus').textContent='モデル準備 '+Math.round(p.progress*100)+'% · '+p.text}})}$('aiStatus').textContent='AIが企画を考えています…';const res=await engine.chat.completions.create({messages:[{role:'system',content:'あなたはプロダクト企画の相談役です。日本語で簡潔に答えてください。指定されたアイデアから、対象ユーザー、解決する課題、提供する価値、最小限の機能3つ、Solanaの活用方法、明日できる最初の一歩を提案してください。誇大な主張や価格予測はしないでください。'},{role:'user',content:$('title').value+'\n'+$('idea').value}],temperature:.7,max_tokens:700});const result=res.choices[0]?.message?.content;if(!result)throw Error('AIから結果を取得できませんでした。');$('plan').value=result;$('aiStatus').textContent='✦ AIが生成しました。内容を確認・編集して保存してください。'}catch(e){$('aiStatus').textContent='AIを実行できませんでした：'+e.message}finally{lock(false)}};
async function rpc(){const w=await solana();return new w.Connection('https://api.devnet.solana.com','confirmed')}
async function checkProof(p){if(busy)return;lock(true);try{const c=await rpc();const r=await c.getSignatureStatuses([p.signature],{searchTransactionHistory:true});const s=r.value[0];if(s?.err)p.status='failed';else if(s?.confirmationStatus==='confirmed'||s?.confirmationStatus==='finalized')p.status='confirmed';else{toast('まだ確認できません。Explorerでも確認してください。');return}const next={...current,proofs:current.proofs.map(x=>x.signature===p.signature?p:x)};if(persist([next,...ideas.filter(x=>x.id!==next.id)])){current=next;renderProof();toast(p.status==='confirmed'?'記録を確認しました':'トランザクションが失敗しました')}}catch(e){toast('確認できませんでした：'+e.message)}finally{lock(false)}}
$('record').onclick=async()=>{if(busy)return;if(!$('consent').checked){toast('公開される内容の確認にチェックしてください。');return}const x=save(true);if(!x)return;const hash=await digest(x);if((x.proofs||[]).some(p=>p.hash===hash&&p.status!=='failed')){toast('この内容は送信済みです。記録の状態を確認してください。');return}lock(true);let signature=null;try{if(!await connect())return;const w=await solana();const connection=new w.Connection('https://api.devnet.solana.com','confirmed');const payer=new w.PublicKey(provider.publicKey.toString());if(await connection.getBalance(payer)<10000)throw Error('DevnetのテストSOLが不足しています。「テストSOLを取得」から補充してください。');const block=await connection.getLatestBlockhash('confirmed');const tx=new w.Transaction({feePayer:payer,blockhash:block.blockhash,lastValidBlockHeight:block.lastValidBlockHeight}).add(new w.TransactionInstruction({keys:[{pubkey:payer,isSigner:true,isWritable:false}],programId:new w.PublicKey('MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr'),data:Buffer.from('IDEA-FORGE:v1:sha256:'+hash)}));$('record').textContent='ウォレットでDevnetへの署名を確認…';const signed=await provider.signTransaction(tx);signature=await connection.sendRawTransaction(signed.serialize(),{skipPreflight:false});const proof={hash,signature,status:'pending',snapshot:canonical(x),created:new Date().toISOString()};current={...x,proofs:[...(x.proofs||[]),proof]};const saved=persist([current,...ideas.filter(v=>v.id!==x.id)]);renderProof();if(!saved){download(current,'idea-forge-receipt.json');throw Error('送信済みですが端末保存に失敗しました。書き出した控えを保管してください。')} $('record').textContent='ネットワークの確認待ち…';const result=await connection.confirmTransaction({signature,...block},'confirmed');proof.status=result.value.err?'failed':'confirmed';persist([current,...ideas.filter(v=>v.id!==x.id)]);renderProof();toast(proof.status==='confirmed'?'Solana Devnetへの記録を確認しました。':'トランザクションが失敗しました。')}catch(e){toast(signature?'送信済みです。再送せず、記録の状態を確認してください。':'記録できませんでした：'+e.message)}finally{lock(false);$('record').textContent='≋ Solanaに記録する'}};
for(const id of ['title','idea','plan','category'])$(id).addEventListener('input',()=>{$('saveStatus').textContent='未保存の変更があります。';renderProof()});
window.addEventListener('beforeunload',e=>{if(busy||(current&&$('editor').open&&canonical(formValue())!==canonical(current))){e.preventDefault();e.returnValue=''}});
render();
